// Join: opening a place the website handed over.
//
// The site's Play button is a fieldbrik:// link carrying the place file's URL
// and the identity it already knows: account name, account id, the six avatar
// colours and the face id. The client parses it, downloads the place to a temp
// file, and plays it with that name and appearance.
//
// There is no sign-in and no ticket yet, so the identity is whatever the link
// says. That is deliberate for single-player: the link is generated by the site
// from the signed-in session, and nothing is trusted for anything but the name
// and colours on the local screen. Once there is a server to talk to, the id has
// to be proved rather than carried.
//
// The client also registers the scheme under HKCU on startup, so pressing Play
// in a browser opens this exe without an installer.

#pragma once

#include <DirectXMath.h>

#include <string>

namespace fieldbrik {

struct JoinInfo {
  std::wstring placeUrl;
  std::wstring tempPath;
  std::wstring name;
  std::wstring userId;
  std::string face;

  // head, torso, left arm, right arm, left leg, right leg: the order the site
  // stores them in.
  DirectX::XMFLOAT3 colours[6]{};
  bool hasColours = false;
};

// True when the command line argument is a fieldbrik:// launch link.
bool IsJoinUrl(const std::wstring& argument);

// Reads a launch link. Returns false, with `error` set, when it has no place or
// a colour is malformed.
bool ParseJoinUrl(const std::wstring& argument, JoinInfo& out, std::wstring& error);

// Downloads the place to a temporary .rbxl and puts the path in `tempPath`.
bool DownloadPlace(const std::wstring& url, std::wstring& tempPath,
                   std::wstring& error);

// Points HKCU\Software\Classes\fieldbrik at this executable. Safe to call every
// run; failures are ignored because the client still plays places opened by
// hand.
void RegisterJoinScheme();

}  // namespace fieldbrik
